import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.gtmkOXzY.js";const b=JSON.parse('{"title":"Player journey","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/player-journey.md","filePath":"ms-flightsim/player-journey.md","lastUpdated":null}'),i={name:"ms-flightsim/player-journey.md"};function o(n,t,l,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="player-journey" tabindex="-1">Player journey <a class="header-anchor" href="#player-journey" aria-label="Permalink to &quot;Player journey&quot;">​</a></h1><p>A new player goes from the flight school to their first paid job in three steps: theory exam, practical test, then the job board. Everything after that is earned by flying.</p><h2 id="_1-get-a-licence" tabindex="-1">1. Get a licence <a class="header-anchor" href="#_1-get-a-licence" aria-label="Permalink to &quot;1. Get a licence&quot;">​</a></h2><p>At the Flight Instructor NPC at LSIA. Admins can add instructors at other airports from <code>/adminps</code>.</p><table tabindex="0"><thead><tr><th>Licence</th><th>Theory exam</th><th>Practical test</th><th>Aircraft</th></tr></thead><tbody><tr><td>Plane</td><td>$1,500 · 15 questions · 70% to pass</td><td>$55,000 · 8 phases</td><td>Mammatus</td></tr><tr><td>Helicopter</td><td>$1,500 · 15 questions from a separate bank</td><td>$45,000 · 6 phases</td><td>Conada</td></tr></tbody></table><ul><li><strong>Plane practical</strong>: controls brief, taxi, take-off, climb to 3,000 ft, land at Sandy Shores, depart Sandy, return to LSIA, park on the apron.</li><li><strong>Helicopter practical</strong>: brief, hover, Mission Row, an in-air checkpoint in the hills, return to LSIA, land.</li><li>A failed theory exam can be retaken after 10 minutes.</li><li>Failing or cancelling the practical keeps the theory pass for the rest of the session; only the fee is lost.</li></ul><p><strong>When the pilot job is required</strong> (<code>Config.PilotAuthorization.enabled = true</code>), a player without it must be authorised by a player on the pilot job before taking the exam or the practical. The authorisation lasts until they disconnect. Players on the pilot job train without it.</p><h2 id="_2-earn-specialist-ratings" tabindex="-1">2. Earn specialist ratings <a class="header-anchor" href="#_2-earn-specialist-ratings" aria-label="Permalink to &quot;2. Earn specialist ratings&quot;">​</a></h2><p>From the Flight Instructor NPC. Ratings cost nothing; each practical is a real mission, and a failed attempt can be retried after 10 minutes.</p><table tabindex="0"><thead><tr><th>Rating</th><th>Needs</th><th>Flight hours</th><th>Completed jobs</th></tr></thead><tbody><tr><td>Multi-engine</td><td>Plane licence</td><td>20</td><td>8</td></tr><tr><td>Turbine</td><td>Multi-engine</td><td>30</td><td>12</td></tr><tr><td>Jet</td><td>Turbine</td><td>40</td><td>15</td></tr><tr><td>Skylift</td><td>Helicopter licence</td><td>25</td><td>10</td></tr><tr><td>Medevac</td><td>Skylift</td><td>—</td><td>5</td></tr><tr><td>Firefighting</td><td>Medevac</td><td>—</td><td>5</td></tr></tbody></table><p>Players on the ambulance job need only the helicopter licence for Medevac; fire-job players need only the helicopter licence for Medevac and Firefighting.</p><h2 id="_3-rank-up" tabindex="-1">3. Rank up <a class="header-anchor" href="#_3-rank-up" aria-label="Permalink to &quot;3. Rank up&quot;">​</a></h2><p>Rank score = flight hours + a bonus for badges and completed jobs (the bonus is capped at 20). Each rank above Student adds 2% to pay, so an Instructor earns 18% more.</p><table tabindex="0"><thead><tr><th>Rank</th><th>Score</th></tr></thead><tbody><tr><td>Student</td><td>0</td></tr><tr><td>Amateur</td><td>4</td></tr><tr><td>Private</td><td>8</td></tr><tr><td>First Officer</td><td>14</td></tr><tr><td>Senior First Officer</td><td>20</td></tr><tr><td>Captain</td><td>28</td></tr><tr><td>Flight Captain</td><td>40</td></tr><tr><td>Senior Flight Captain</td><td>60</td></tr><tr><td>Commercial Captain</td><td>80</td></tr><tr><td>Instructor</td><td>100</td></tr></tbody></table><h2 id="_4-own-aircraft" tabindex="-1">4. Own aircraft <a class="header-anchor" href="#_4-own-aircraft" aria-label="Permalink to &quot;4. Own aircraft&quot;">​</a></h2><p>The dealer NPC at LSIA sells and rents 29 aircraft. Buying needs the matching base licence (plane or helicopter).</p><table tabindex="0"><thead><tr><th>Term</th><th>Default</th></tr></thead><tbody><tr><td>Rental length</td><td>120 minutes</td></tr><tr><td>Rental deposit</td><td>40% of the price</td></tr><tr><td>Selling back</td><td>30% of the price</td></tr><tr><td>Insurance</td><td>1% of the price per 30 days</td></tr></tbody></table><p>Owners store aircraft in the hangar and pay for fuel ($8/gal), repairs ($10/point), maintenance and paint ($5,000).</p><h2 id="_5-fly-safely" tabindex="-1">5. Fly safely <a class="header-anchor" href="#_5-fly-safely" aria-label="Permalink to &quot;5. Fly safely&quot;">​</a></h2><p>Crashes add strikes.</p><table tabindex="0"><thead><tr><th>Strikes</th><th>Effect</th></tr></thead><tbody><tr><td>1–2</td><td>Warning</td></tr><tr><td>3</td><td>Dealer prices +25%</td></tr><tr><td>5</td><td>Dealer closed to them for 24 hours</td></tr><tr><td>8</td><td>Dealer prices +75%</td></tr><tr><td>10</td><td>Permanently blacklisted from the dealer until an admin lifts it</td></tr></tbody></table><p>The <strong>Safety Refresher</strong> course ($20,000, once per 24 hours, needs at least one strike) removes one strike. It ends with one theory question and 60 seconds to answer; a wrong answer or a timeout loses the fee and removes nothing. It never lifts a blacklist. The logbook shows each pilot&#39;s safety record.</p><h2 id="the-pilot-tablet" tabindex="-1">The pilot tablet <a class="header-anchor" href="#the-pilot-tablet" aria-label="Permalink to &quot;The pilot tablet&quot;">​</a></h2><p><code>/pilottablet</code> opens the pilot&#39;s own tabs: Logbook, Badges, Map, Flight Plan and Sub-Company, plus Company for captains. The other tabs open at their NPCs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Opens at</th></tr></thead><tbody><tr><td>Jobs, Routes, Other</td><td>Cargo / job NPC</td></tr><tr><td>Training</td><td>Flight Instructor</td></tr><tr><td>Shop</td><td>Aircraft dealer</td></tr><tr><td>Paint</td><td>Painter</td></tr><tr><td>Services</td><td>Fuel and service zone</td></tr></tbody></table><p><code>/myflights</code> lists your 25 most recent flights. A flight is recorded when it lasts at least 30 seconds and covers at least 500 m.</p>',26)])])}const f=e(i,[["render",o]]);export{b as __pageData,f as default};
